CREATE TEMP TABLE rows AS
SELECT 'W' kind, o.key idx, o.value omod, k.value kw, c.value codex
FROM Records lo, json_each(lo.Data,'$.Items') o
JOIN Records lk ON lk.FormKey='001D36:darkstar.esm'
JOIN json_each(lk.Data,'$.Items') k ON k.key=o.key
JOIN Records lc ON lc.FormKey='001D35:darkstar.esm'
JOIN json_each(lc.Data,'$.Items') c ON c.key=o.key
WHERE lo.FormKey='001D37:darkstar.esm'
UNION ALL
SELECT 'A', o.key, o.value, k.value, c.value
FROM Records lo, json_each(lo.Data,'$.Items') o
JOIN Records lk ON lk.FormKey='009E08:darkstar.esm'
JOIN json_each(lk.Data,'$.Items') k ON k.key=o.key
JOIN Records lc ON lc.FormKey='001D32:darkstar.esm'
JOIN json_each(lc.Data,'$.Items') c ON c.key=o.key
WHERE lo.FormKey='009E09:darkstar.esm';
UPDATE rows SET omod=substr(omod,1,instr(omod,' ')-1) WHERE instr(omod,' ')>0;
UPDATE rows SET kw=substr(kw,1,instr(kw,' ')-1) WHERE instr(kw,' ')>0;
UPDATE rows SET codex=substr(codex,1,instr(codex,' ')-1) WHERE instr(codex,' ')>0;
-- ## Codex rows per kind, distinct codices, codex signature
SELECT r.kind, COUNT(*) rows_, COUNT(DISTINCT r.omod) omods, COUNT(DISTINCT r.codex) codices, (SELECT group_concat(DISTINCT x.Signature) FROM Records x JOIN rows y ON y.codex=x.FormKey WHERE y.kind=r.kind) codexsig FROM rows r GROUP BY r.kind;
-- ## Omod attach points in codex rows
SELECT r.kind, edid(json_extract(m.Data,'$.AttachPoint')) ap, COUNT(*) FROM rows r LEFT JOIN Records m ON m.FormKey=r.omod GROUP BY 1,2 ORDER BY 1,3 DESC;
-- ## Omods in codex rows with a Value property (and its function and value)
CREATE TEMP TABLE vp AS SELECT r.kind, r.omod, json_extract(p.value,'$.FunctionType') fn, json_extract(p.value,'$.Value') v, json_extract(p.value,'$.Value1') v1 FROM rows r JOIN Records m ON m.FormKey=r.omod, json_each(m.Data,'$.Properties') p WHERE json_extract(p.value,'$.Property')='Value';
SELECT kind, fn, v, v1, COUNT(*) FROM vp GROUP BY 1,2,3,4 ORDER BY 1,5 DESC;
-- ## Codex rows whose omod has NO Value property
SELECT r.kind, COUNT(*) FROM rows r WHERE r.omod NOT IN (SELECT omod FROM vp) GROUP BY 1;
-- ## Origin plugins of rows
SELECT kind, substr(omod,8) plugin, COUNT(*) FROM rows GROUP BY 1,2;
-- ## Sample of 12 rows
SELECT kind, idx, edid(omod) omod, edid(kw) kw, edid(codex) codex FROM rows WHERE idx<6 ORDER BY kind, idx;
-- ## Same codex used for weapon and armor
SELECT edid(codex), COUNT(DISTINCT kind) FROM rows GROUP BY codex HAVING COUNT(DISTINCT kind)>1;
-- ## Codex rows per codex (how many omods share one codex)
SELECT kind, n, COUNT(*) codices FROM (SELECT kind, codex, COUNT(*) n FROM rows GROUP BY 1,2) GROUP BY 1,2 ORDER BY 1,2;

CREATE TEMP TABLE cx AS
SELECT DISTINCT 'W' kind, substr(c.value,1,instr(c.value,' ')-1) codex FROM Records l, json_each(l.Data,'$.Items') c WHERE l.FormKey='001D35:darkstar.esm'
UNION SELECT DISTINCT 'A', substr(c.value,1,instr(c.value,' ')-1) FROM Records l, json_each(l.Data,'$.Items') c WHERE l.FormKey='001D32:darkstar.esm';
CREATE TEMP TABLE suite AS
SELECT x.kind, x.codex, m.EditorID mi_edid, m.Name mi_name,
 json_extract(m.Data,'$.Value') mi_value,
 json_array_length(json_extract(m.Data,'$.Resources')) n_res,
 substr(json_extract(m.Data,'$.Resources[0].Resource'),1,13+length(substr(json_extract(m.Data,'$.Resources[0].Resource'),8))-1) res_raw,
 json_extract(m.Data,'$.Resources[0].Resource') res
FROM cx x JOIN Records m ON m.FormKey=x.codex;
UPDATE suite SET res=substr(res,1,instr(res,' ')-1) WHERE instr(res,' ')>0;
ALTER TABLE suite ADD COLUMN avif TEXT; ALTER TABLE suite ADD COLUMN produce TEXT; ALTER TABLE suite ADD COLUMN rtype TEXT;
UPDATE suite SET avif=(SELECT json_extract(Data,'$.ActorValue') FROM Records WHERE FormKey=suite.res), produce=(SELECT json_extract(Data,'$.Produce') FROM Records WHERE FormKey=suite.res), rtype=(SELECT json_extract(Data,'$.ResourceType') FROM Records WHERE FormKey=suite.res);
UPDATE suite SET produce=substr(produce,1,instr(produce,' ')-1) WHERE instr(produce,' ')>0;
-- ## Suite completeness per kind
SELECT kind, COUNT(*) codices, SUM(n_res=1) one_res, SUM(avif IS NOT NULL) has_avif, SUM(produce IS NOT NULL) has_produce, COUNT(DISTINCT res) distinct_res, COUNT(DISTINCT mi_value) values_ FROM suite GROUP BY kind;
-- ## MiscItem value and keywords pattern
SELECT mi_value, COUNT(*) FROM suite GROUP BY 1;
-- ## Produce recipe = codex recipe? bench, created object matches, components
SELECT s.kind, edid(json_extract(c.Data,'$.WorkbenchKeyword')) bench, (substr(json_extract(c.Data,'$.CreatedObject'),1,instr(json_extract(c.Data,'$.CreatedObject'),' ')-1)=s.codex) makes_codex, json_array_length(json_extract(c.Data,'$.Conditions')) nconds, json_array_length(json_extract(c.Data,'$.ConstructibleComponents')) ncomp, COUNT(*) FROM suite s LEFT JOIN Records c ON c.FormKey=s.produce GROUP BY 1,2,3,4,5;
-- ## Codex recipe components (distinct sets)
SELECT json_extract(c.Data,'$.ConstructibleComponents') comps, json_extract(c.Data,'$.RecipeFilters') filt, COUNT(*) FROM suite s JOIN Records c ON c.FormKey=s.produce GROUP BY 1,2 ORDER BY 3 DESC;
-- ## Codex recipe conditions (functions and params), distinct shapes
CREATE TEMP TABLE cc AS SELECT s.codex, c.FormKey cobj, j.key i, json_extract(j.value,'$.Data.Function') fn, json_extract(j.value,'$.Data.FirstParameter') p1, json_extract(j.value,'$.Flags') fl FROM suite s JOIN Records c ON c.FormKey=s.produce, json_each(c.Data,'$.Conditions') j;
SELECT i, fn, fl, CASE WHEN fn='IsTrueForConditionForm' THEN edid(substr(p1,1,instr(p1,' ')-1)) ELSE 'research' END p, COUNT(*) FROM cc GROUP BY 1,2,3,4 ORDER BY 1,5 DESC;
-- ## Researches that spend the resource
CREATE TEMP TABLE rs AS SELECT s.codex, r.FormKey rspj, r.EditorID FROM suite s JOIN Refs f ON f.ToFormKey=s.res AND f.FromSignature='ResearchProject' JOIN Records r ON r.FormKey=f.FromFormKey;
SELECT COUNT(DISTINCT codex) codices_with_rspj, COUNT(*) rspjs FROM rs;
-- ## Research shape: items, perks, required projects, conditions
SELECT json_array_length(json_extract(r.Data,'$.RequiredItems')) items, json_extract(r.Data,'$.RequiredItems[0].RequiredCount') cnt, json_extract(r.Data,'$.RequiredPerks') perks, json_array_length(json_extract(r.Data,'$.RequiredProjects')) reqp, json_array_length(json_extract(r.Data,'$.Conditions')) conds, edid(substr(json_extract(r.Data,'$.CategoryKeyword'),1,instr(json_extract(r.Data,'$.CategoryKeyword'),' ')-1)) cat, json_extract(r.Data,'$.Tier') tier, COUNT(*) FROM rs JOIN Records r ON r.FormKey=rs.rspj GROUP BY 1,2,3,4,5,6,7 ORDER BY 8 DESC;
-- ## Codex recipe conditions point at the codex's own research?
SELECT COUNT(*) total, SUM(EXISTS(SELECT 1 FROM rs WHERE rs.codex=cc.codex AND instr(cc.p1, substr(rs.rspj,1,6))>0)) own_research FROM cc WHERE fn='IsResearchComplete';
-- ## Recipes that spend the resource (rank recipes): bench, filter, count, conditions
CREATE TEMP TABLE rk AS SELECT s.kind, s.codex, c.FormKey cobj, c.Data FROM suite s JOIN Refs f ON f.ToFormKey=s.res AND f.FromSignature='ConstructibleObject' JOIN Records c ON c.FormKey=f.FromFormKey;
SELECT kind, edid(substr(json_extract(Data,'$.WorkbenchKeyword'),1,instr(json_extract(Data,'$.WorkbenchKeyword'),' ')-1)) bench, json_extract(Data,'$.RecipeFilters') filt, json_extract(Data,'$.AmountProduced') amt, json_array_length(json_extract(Data,'$.ConstructibleComponents')) ncomp, json_array_length(json_extract(Data,'$.Conditions')) nconds, COUNT(*) FROM rk GROUP BY 1,2,3,4,5,6 ORDER BY 7 DESC;
-- ## Rank recipes per codex
SELECT kind, n, COUNT(*) FROM (SELECT kind, codex, COUNT(*) n FROM rk GROUP BY 1,2) GROUP BY 1,2;
-- ## Rank recipe created omod attach points
SELECT kind, edid(substr(json_extract(m.Data,'$.AttachPoint'),1,instr(json_extract(m.Data,'$.AttachPoint'),' ')-1)) ap, COUNT(*) FROM rk JOIN Records m ON m.FormKey=substr(json_extract(rk.Data,'$.CreatedObject'),1,instr(json_extract(rk.Data,'$.CreatedObject'),' ')-1) GROUP BY 1,2;
-- ## AVIF shape
SELECT json_extract(a.Data,'$.Type') t, json_extract(a.Data,'$.Flags') fl, json_extract(a.Data,'$.DefaultValue') dv, COUNT(*) FROM suite s JOIN Records a ON a.FormKey=substr(s.avif,1,instr(s.avif,' ')-1) GROUP BY 1,2,3;
-- ## Resource shape
SELECT json_extract(r.Data,'$.Rarity') rar, json_extract(r.Data,'$.Keywords') kws, edid(substr(json_extract(r.Data,'$.Interval'),1,instr(json_extract(r.Data,'$.Interval'),' ')-1)) iv, COUNT(*) FROM suite s JOIN Records r ON r.FormKey=s.res GROUP BY 1,2,3;
-- ## MiscItem shape
SELECT json_extract(m.Data,'$.Keywords') kws, json_extract(m.Data,'$.Model.File.GivenPath') mdl, json_extract(m.Data,'$.Weight') w, COUNT(*) FROM suite s JOIN Records m ON m.FormKey=s.codex GROUP BY 1,2,3;
-- ## Naming samples
SELECT kind, mi_edid, mi_name, edid(res) res, rtype, edid(substr(avif,1,instr(avif,' ')-1)) avif, edid(produce) cobj FROM suite ORDER BY kind, mi_edid LIMIT 8;

CREATE TEMP TABLE cx AS
SELECT DISTINCT 'W' kind, c.value codex FROM Records l, json_each(l.Data,'$.Items') c WHERE l.FormKey='001D35:darkstar.esm'
UNION SELECT DISTINCT 'A', c.value FROM Records l, json_each(l.Data,'$.Items') c WHERE l.FormKey='001D32:darkstar.esm';
CREATE TEMP TABLE res AS SELECT x.kind, x.codex, json_extract(m.Data,'$.Resources[0].Resource') res FROM cx x JOIN Records m ON m.FormKey=x.codex;
CREATE TEMP TABLE rk AS SELECT s.kind, s.codex, c.FormKey cobj, c.EditorID, c.Data FROM res s JOIN Refs f ON f.ToFormKey=s.res AND f.FromSignature='ConstructibleObject' JOIN Records c ON c.FormKey=f.FromFormKey WHERE json_extract(c.Data,'$.WorkbenchKeyword') NOT LIKE '001A54:%';
-- ## Rank recipe conditions
SELECT kind, json_extract(j.value,'$.Data.Function') fn, edid(json_extract(j.value,'$.Data.FirstParameter')) p1, json_extract(j.value,'$.ComparisonValue') cv, COUNT(*) FROM rk, json_each(rk.Data,'$.Conditions') j GROUP BY 1,2,3,4 ORDER BY 5 DESC;
-- ## Rank recipes by created omod origin
SELECT kind, substr(json_extract(Data,'$.CreatedObject'),8) origin, COUNT(*) FROM rk GROUP BY 1,2;
-- ## Rank recipes by EditorID prefix
SELECT kind, substr(EditorID,1,instr(substr(EditorID,4),'_')+3) pre, COUNT(*) FROM rk GROUP BY 1,2 ORDER BY 3 DESC;
-- ## Codex research EditorIDs and the VIP condition comparison
SELECT r.EditorID, json_extract(r.Data,'$.Conditions[0].ComparisonValue') cv, json_extract(r.Data,'$.SortingPriority') sp FROM res s JOIN Refs f ON f.ToFormKey=s.res AND f.FromSignature='ResearchProject' JOIN Records r ON r.FormKey=f.FromFormKey ORDER BY r.EditorID LIMIT 6;
-- ## Other legendary-bench recipes that spend a codex resource (not the codex recipe)
SELECT s.kind, c.EditorID, edid(json_extract(c.Data,'$.CreatedObject')) made FROM res s JOIN Refs f ON f.ToFormKey=s.res AND f.FromSignature='ConstructibleObject' JOIN Records c ON c.FormKey=f.FromFormKey WHERE json_extract(c.Data,'$.WorkbenchKeyword') LIKE '001A54:%' AND json_extract(c.Data,'$.CreatedObject')<>s.codex LIMIT 15;
-- ## Codices with no own research
SELECT s.kind, edid(s.codex) FROM res s WHERE NOT EXISTS (SELECT 1 FROM Refs f WHERE f.ToFormKey=s.res AND f.FromSignature='ResearchProject');

-- ## Codex MiscItems: value, resource, keywords count, model
SELECT EditorID, Name, json_extract(Data,'$.Value') v, edid(json_extract(Data,'$.Resources[0].Resource')) res, json_array_length(json_extract(Data,'$.Keywords')) nkw, json_extract(Data,'$.Model.File.GivenPath') mdl FROM Records WHERE Signature='MiscItem' AND EditorID LIKE '%Codex%';
-- ## Resources: type, avif, produce, rarity, interval
SELECT EditorID, Name, json_extract(Data,'$.ResourceType') rt, edid(json_extract(Data,'$.ActorValue')) av, edid(json_extract(Data,'$.Produce')) prod, json_extract(Data,'$.Rarity') rar FROM Records WHERE Signature='Resource' AND EditorID LIKE '%Codex%';
-- ## Codex recipes
SELECT EditorID, edid(json_extract(Data,'$.WorkbenchKeyword')) bench, edid(json_extract(Data,'$.CreatedObject')) made, json_extract(Data,'$.ConstructibleComponents') comps, json_extract(Data,'$.Conditions') conds FROM Records WHERE Signature='ConstructibleObject' AND EditorID LIKE '%Codex%';
-- ## Codex researches
SELECT EditorID, Name, json_extract(Data,'$.RequiredItems') items, json_extract(Data,'$.RequiredPerks') perks, json_extract(Data,'$.RequiredProjects') reqp, json_extract(Data,'$.Conditions') conds FROM Records WHERE Signature='ResearchProject' AND EditorID LIKE '%Codex%';
-- ## Legendary OMODs: ap, properties summary
SELECT m.EditorID, m.Name, edid(json_extract(m.Data,'$.AttachPoint')) ap, (SELECT group_concat(json_extract(p.value,'$.Property')||':'||json_extract(p.value,'$.FunctionType')||':'||coalesce(edid(json_extract(p.value,'$.Record')),json_extract(p.value,'$.Value')),' | ') FROM json_each(m.Data,'$.Properties') p) props FROM Records m WHERE m.IsOverride=0 AND json_extract(m.Data,'$.AttachPoint') IN ('000847:darkstar.esm','000853:darkstar.esm','000854:darkstar.esm');
-- ## Recipes that make those OMODs
SELECT c.EditorID, edid(json_extract(c.Data,'$.CreatedObject')) omod, edid(json_extract(c.Data,'$.WorkbenchKeyword')) bench, json_extract(c.Data,'$.ConstructibleComponents') comps, json_extract(c.Data,'$.Conditions') conds FROM Records c JOIN Records m ON m.FormKey=json_extract(c.Data,'$.CreatedObject') WHERE c.Signature='ConstructibleObject' AND json_extract(m.Data,'$.AttachPoint') IN ('000847:darkstar.esm','000853:darkstar.esm','000854:darkstar.esm');
-- ## Who points at the legendary OMODs (besides recipes)
SELECT edid(f.ToFormKey) omod, f.FromSignature, f.FromEditorID, f.Path FROM Refs f JOIN Records m ON m.FormKey=f.ToFormKey WHERE json_extract(m.Data,'$.AttachPoint') IN ('000847:darkstar.esm','000853:darkstar.esm','000854:darkstar.esm') AND f.FromSignature<>'ConstructibleObject';
